`timescale 1ns / 1ps
`default_nettype none
// vio_hook - the JTAG automation hook (spec: docs/spec/vio_hook.md, PROTOCOL.md section 10).
// One Vivado VIO core (vio_0, generated by scripts/vio_ip.tcl during the build): outputs ovr_en,
// ovr_sw[15:0], ovr_btn[4:0]; inputs leds, seg7_val, seg7_dp, uart_busy, seg7_txt. sw / btn come from the
// VIO when ovr_en = 1, else from the pins. ovr_en starts at 0, so the board behaves exactly as
// without the hook until a script enables it. With HAS_VIO = 0 there is no VIO.
// Every pin first goes through a 2-flop synchroniser (ASYNC_REG), then the mux: sw / btn are
// clk-domain signals with no logic between a pin and its first flop (CDC-10), and the reset
// request btn[0] is a clean flop output (clk_rst samples it synchronously). In simulation the
// testbench supplies a stub vio_0 (tb/tb_vio_hook.v).

module vio_hook #(
    parameter HAS_VIO = 1
) (
    input  wire        clk,
    input  wire [15:0] sw_pin,
    input  wire [4:0]  btn_pin,        // bit 0 BTNC, 1 BTNL, 2 BTNR, 3 BTNU, 4 BTND
    output wire [15:0] sw,
    output wire [4:0]  btn,
    input  wire [15:0] leds,
    input  wire [31:0] seg7_val,
    input  wire [7:0]  seg7_dp,
    input  wire [31:0] seg7_txt,
    input  wire        uart_busy
);

    wire        ovr_en;
    wire [15:0] ovr_sw;
    wire [4:0]  ovr_btn;

    generate
        if (HAS_VIO != 0) begin : g_vio
            vio_0 u_vio (.clk(clk), .probe_in0(leds), .probe_in1(seg7_val), .probe_in2(seg7_dp),
                         .probe_in3(uart_busy), .probe_in4(seg7_txt), .probe_out0(ovr_en), .probe_out1(ovr_sw),
                         .probe_out2(ovr_btn));
        end else begin : g_no_vio
            assign ovr_en = 1'b0; assign ovr_sw = 16'd0; assign ovr_btn = 5'd0;
        end
    endgenerate

    (* ASYNC_REG = "TRUE" *) reg [15:0] sw_s1 = 16'd0, sw_s2 = 16'd0;
    (* ASYNC_REG = "TRUE" *) reg [4:0]  bt_s1 = 5'd0,  bt_s2 = 5'd0;
    always @(posedge clk) begin
        sw_s1 <= sw_pin;  sw_s2 <= sw_s1;
        bt_s1 <= btn_pin; bt_s2 <= bt_s1;
    end

    assign sw  = ovr_en ? ovr_sw  : sw_s2;
    assign btn = ovr_en ? ovr_btn : bt_s2;

endmodule

`default_nettype wire
